  --text-primary:   #e8eaf0;
  --text-secondary: #9499b0;
  --text-muted:     #5c6180;

  --accent-red:     #e05252;
  --accent-red-hover:#c93e3e;
  --accent-red-active:#b33434;

  --border-subtle:  rgba(255,255,255,.08);
  --border-focus:   #6b8cff;

  --radius-card:    12px;
  --radius-btn:     8px;
  --radius-dialog:  16px;

  --shadow-card:    0 4px 24px rgba(0,0,0,.5);
  --shadow-dialog:  0 24px 64px rgba(0,0,0,.7);

  --transition:     150ms ease;
}

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--bg-dialog);
  color: var(--text-primary);
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; outline: 3px solid var(--border-focus); outline-offset: 2px; }

/* ── Page layout ──────────────────────────────────────────── */
body {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

header {
  border-bottom: 1px solid var(--border-subtle);
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  gap: .75rem;
}

header svg { color: var(--text-secondary); flex-shrink: 0; }

header h1 {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -.02em;
  color: var(--text-primary);
}

main {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  gap: 1.5rem;
}

/* ── Image card ───────────────────────────────────────────── */
.image-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  width: 100%;
  max-width: 480px;
  overflow: hidden;
}

.image-card__preview {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  display: block;
  background: #13162060;
}

/* Placeholder image via CSS gradient */
.image-card__preview--placeholder {
  background:
    linear-gradient(135deg, #1c2040 0%, #2a1f3d 50%, #1a2540 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.image-card__preview--placeholder svg {
  width: 72px;
  height: 72px;
  opacity: .4;
}

.image-card__body {
  padding: 1.25rem 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: .75rem;
}

.image-card__meta {
  display: flex;
  flex-direction: column;
  gap: .2rem;
}

.image-card__name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.image-card__info {
  font-size: .8125rem;
  color: var(--text-secondary);
}

.image-card__actions {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

/* ── Buttons ──────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  padding: .55rem 1.1rem;
  font-size: .875rem;
  font-weight: 500;
  border-radius: var(--radius-btn);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
