.btn--ghost:hover { background: var(--bg-card-hover); color: var(--text-primary); }
.btn--ghost:active { background: #242840; }

/* Danger (delete trigger) */
.btn--danger {
  background: rgba(224,82,82,.12);
  color: var(--accent-red);
  border-color: rgba(224,82,82,.25);
}
.btn--danger:hover { background: rgba(224,82,82,.22); border-color: rgba(224,82,82,.45); }
.btn--danger:active { background: rgba(224,82,82,.30); }

/* Solid danger (confirm inside dialog) */
.btn--danger-solid {
  background: var(--accent-red);
  color: #fff;
  border-color: var(--accent-red);
}
.btn--danger-solid:hover { background: var(--accent-red-hover); border-color: var(--accent-red-hover); }
.btn--danger-solid:active { background: var(--accent-red-active); }

/* ── Dialog backdrop / native <dialog> ───────────────────── */
dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  background: transparent;
  color: inherit;
  max-width: 100%;
  /* Hidden by default (JS uses .showModal()) */
