@keyframes dialog-out {
  from { opacity: 1; transform: none; }
  to   { opacity: 0; transform: translateY(-8px) scale(.97); }
}

.dialog__icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(224,82,82,.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-red);
  flex-shrink: 0;
