.dialog__title {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.3;
}

.dialog__description {
  font-size: .875rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

.dialog__filename {
  display: inline-block;
  font-weight: 600;
  color: var(--text-primary);
  word-break: break-all;
}

.dialog__warning {
  display: flex;
  align-items: flex-start;
  gap: .6rem;
  background: rgba(224,82,82,.08);
  border: 1px solid rgba(224,82,82,.2);
  border-radius: 8px;
  padding: .75rem 1rem;
  font-size: .8125rem;
  color: #e07878;
  line-height: 1.5;
}

.dialog__warning svg { flex-shrink: 0; margin-top: 1px; }

.dialog__footer {
  display: flex;
